package com.jobproof.modules.aigateway.security;
import static org.junit.jupiter.api.Assertions.*;import java.util.Base64;import org.junit.jupiter.api.Test;
class ApiKeyCipherTest {private final String key=Base64.getEncoder().encodeToString(new byte[32]);@Test void roundTripsAndUsesRandomNonce(){ApiKeyCipher c=new ApiKeyCipher(key);String a=c.encrypt("sk-secret"),b=c.encrypt("sk-secret");assertNotEquals(a,b);assertEquals("sk-secret",c.decrypt(a));}@Test void rejectsInvalidMasterKeyAndTampering(){assertThrows(IllegalStateException.class,()->new ApiKeyCipher("bad"));ApiKeyCipher c=new ApiKeyCipher(key);byte[]v=Base64.getDecoder().decode(c.encrypt("secret"));v[v.length-1]^=1;assertThrows(IllegalArgumentException.class,()->c.decrypt(Base64.getEncoder().encodeToString(v)));}@Test void masks(){assertEquals("sk-****7890",ApiKeyMasker.mask("sk-1234567890"));assertEquals("****",ApiKeyMasker.mask("secret"));}}